components.css:
.ds-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 18px;border:1px solid var(--tfm-border-strong, #9c9ca4);border-radius:var(--tfm-radius-md, 8px);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);font-size:var(--tfm-text-sm, 0.875rem);font-weight:650;line-height:var(--tfm-leading-body, 1.65);cursor:pointer;transition:background-color var(--tfm-fast, 160ms ease-out),color var(--tfm-fast, 160ms ease-out);background:var(--tfm-red-dark, #bb1925);border-color:var(--tfm-red-dark, #bb1925);color:var(--tfm-white, #fff)}
.ds-primary:hover{background:var(--tfm-black, #171719);border-color:var(--tfm-black, #171719)}
.ds-primary:focus-visible{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:4px}
.ds-primary:disabled{cursor:not-allowed;opacity:.55}
@media(prefers-reduced-motion:reduce){.ds-primary{transition:none}}

.ds-secondary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 18px;border:1px solid var(--tfm-border-strong, #9c9ca4);border-radius:var(--tfm-radius-md, 8px);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);font-size:var(--tfm-text-sm, 0.875rem);font-weight:650;line-height:var(--tfm-leading-body, 1.65);cursor:pointer;transition:background-color var(--tfm-fast, 160ms ease-out),color var(--tfm-fast, 160ms ease-out);background:var(--tfm-white, #fff);color:var(--tfm-text-primary, #202023)}
.ds-secondary:hover{background:var(--tfm-light-bg, #f5f5f4)}
.ds-secondary:focus-visible{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:4px}
.ds-secondary:disabled{cursor:not-allowed;opacity:.55}
@media(prefers-reduced-motion:reduce){.ds-secondary{transition:none}}

.ds-field{display:grid;gap:8px;max-width:420px;color:var(--tfm-text-primary, #202023);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);font-size:14px;font-weight:650;line-height:var(--tfm-leading-body, 1.65)}
.ds-field-input{min-width:0;min-height:48px;padding:10px 12px;border:1px solid var(--tfm-border-strong, #9c9ca4);border-radius:var(--tfm-radius-md, 8px);background:var(--tfm-white, #fff);color:var(--tfm-text-primary, #202023);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);font-size:var(--tfm-text-md, 1rem);font-weight:400;line-height:var(--tfm-leading-body, 1.65);caret-color:var(--tfm-red-dark, #bb1925)}
.ds-field-input::placeholder{color:var(--tfm-text-muted, #64646c);opacity:1}
.ds-field-input:focus-visible{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:4px}

.ds-search{display:flex;align-items:center;gap:12px;width:min(100%,560px);border:1px solid var(--tfm-border-strong, #9c9ca4);border-radius:var(--tfm-radius-md, 8px);padding:0 16px;color:var(--tfm-text-muted, #64646c);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif)}
.ds-search:focus-within{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:3px}
.ds-search svg{flex-shrink:0}
.ds-search-input{min-width:0;width:100%;height:48px;border:0;background:transparent;outline:none;font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);font-size:15px;color:var(--tfm-text-primary, #202023);caret-color:var(--tfm-red-dark, #bb1925)}
.ds-search-input::placeholder{color:var(--tfm-text-muted, #64646c);opacity:1}
.ds-search-input:focus-visible{outline:none}

.ds-nav{display:flex;align-items:center;gap:30px;flex-wrap:wrap;border-top:1px solid var(--tfm-light-border, #dddddf);border-bottom:1px solid var(--tfm-light-border, #dddddf);background:var(--tfm-white, #fff);color:var(--tfm-text-primary, #202023);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif)}
.ds-nav-link{display:flex;align-items:center;min-height:52px;padding-top:3px;border-bottom:3px solid transparent;font-size:14px;font-weight:600;line-height:var(--tfm-leading-body, 1.65);text-decoration:none;color:inherit}
.ds-nav-link[aria-current="page"]{color:var(--tfm-red-dark, #bb1925);border-bottom-color:var(--tfm-red, #ed2d39)}
.ds-nav-link:hover{color:var(--tfm-red-dark, #bb1925)}
.ds-nav-link:focus-visible{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:4px;border-radius:var(--tfm-radius-sm, 4px)}
@media(max-width:540px){.ds-nav{display:grid;grid-template-columns:1fr;gap:0}}

.ds-player{position:relative;flex-shrink:0;max-height:50vh;max-height:50dvh;overflow-y:auto;z-index:30;background:var(--tfm-ink-1, #171719);color:var(--tfm-on-dark, #fff);padding-bottom:env(safe-area-inset-bottom,0px);border-top:3px solid var(--tfm-red, #ed2d39);font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif)}
.ds-player-inner{display:flex;align-items:center;gap:16px;min-height:80px;padding-block:12px;width:min(100% - 2 * var(--tfm-gutter, clamp(20px, 3vw, 40px)),var(--tfm-maxw, 1280px));margin-inline:auto}
.ds-player-play{display:grid;place-items:center;width:48px;height:48px;flex-shrink:0;border:0;border-radius:50%;background:var(--tfm-gold, #fff200);color:var(--tfm-black, #171719);cursor:pointer}
.ds-player-play:hover{background:var(--tfm-white, #fff)}
.ds-player-play:focus-visible,.ds-player-title:focus-visible,.ds-player-mute:focus-visible,.ds-player-range:focus-visible,.ds-player-volume-toggle:focus-visible{outline:3px solid var(--tfm-focus, #005fcc);outline-offset:4px;border-radius:var(--tfm-radius-sm, 4px)}
.ds-player-play:disabled{opacity:.55;cursor:not-allowed}
.ds-player-info{min-width:0;flex:1;line-height:1.4}
.ds-player-title{display:block;color:inherit;font-size:15px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-decoration:none}
.ds-player-title:hover{text-decoration:underline}
.ds-player-subtitle{margin:3px 0 0;font-size:12px;color:var(--tfm-on-dark-muted, #ccccd2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ds-player-status{display:flex;align-items:center;gap:8px;margin:0;color:var(--tfm-on-dark-muted, #ccccd2);font-size:12px}
.ds-player-status span{width:6px;height:6px;border-radius:50%;background:currentColor}
.ds-player-status.ds-is-playing{color:var(--tfm-gold, #fff200)}
.ds-player-volume{display:flex;align-items:center;gap:4px;margin-left:12px}
.ds-player-range{width:110px;min-height:44px;margin:0;accent-color:var(--tfm-gold, #fff200)}
.ds-player-mute,.ds-player-volume-toggle{display:grid;place-items:center;width:44px;height:44px;border:0;background:transparent;color:var(--tfm-white, #fff);cursor:pointer}
.ds-player-volume-toggle{display:none}
@media(max-width:640px){.ds-player-inner{min-height:76px;gap:12px;flex-wrap:wrap}.ds-player-play{width:44px;height:44px}.ds-player-status{display:none}.ds-player-volume{order:5;width:100%;margin:0}.ds-player-range{flex:1;width:auto}.ds-player-volume-toggle{display:grid}}

.ds-schedule{list-style:none;margin:0;padding:0;font-family:var(--tfm-font-body, "Archivo", Arial, sans-serif);color:var(--tfm-text-primary, #202023)}
.ds-schedule-row{display:grid;grid-template-columns:156px 56px minmax(0,1fr) auto;align-items:center;gap:24px;padding:20px 16px;border-block:1px solid var(--tfm-light-border, #dddddf);background:var(--tfm-red-soft, #fff1f2)}
.ds-schedule-time{margin:0;font-size:15px;font-weight:650;font-variant-numeric:tabular-nums;line-height:var(--tfm-leading-body, 1.65)}
.ds-schedule-image{display:flex;align-items:center;justify-content:center;width:56px;height:56px;border-radius:var(--tfm-radius-md, 8px);background:var(--tfm-light-bg, #f5f5f4);color:var(--tfm-text-muted, #64646c)}
.ds-schedule-image svg{opacity:.7}
.ds-schedule-title{margin:0;font-size:19px;line-height:1.3;letter-spacing:var(--tfm-tracking-tight, -0.025em);text-wrap:balance;overflow-wrap:anywhere}
.ds-schedule-presenter{margin:4px 0 0;font-size:14px;color:var(--tfm-text-muted, #64646c);line-height:var(--tfm-leading-body, 1.65)}
.ds-schedule-live{display:flex;align-items:center;gap:8px;color:var(--tfm-red-dark, #bb1925);font-size:13px;font-weight:700;line-height:var(--tfm-leading-body, 1.65)}
.ds-schedule-live::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0}
@media(max-width:700px){.ds-schedule-row{grid-template-columns:112px minmax(0,1fr);gap:8px 16px;padding:20px 12px}.ds-schedule-image{display:none}.ds-schedule-time{align-self:start;font-size:13px}.ds-schedule-title{font-size:17px}.ds-schedule-live{grid-column:2}}
